/*
path :           app/admin/page.tsx
tag :            ["miam", "admin", "page", "hub"]
projectId:       new-genesis
type:            page
generic:         false

role:            Hub d'administration de l'application métier. Affiche
                 4 cartes d'entrée (Commandes, Catalogue, Commerces,
                 Livreurs) avec icône, description et lien vers la
                 sous-section correspondante. Page statique (Server
                 Component pur). La protection est portée par le layout
                 admin parent (/miam/admin/layout.tsx).

                 Les liens pointent vers des routes qui seront créées
                 dans les itérations suivantes. Tant qu'elles n'existent
                 pas, elles renverront 404 — c'est attendu et documenté
                 dans chaque carte (« à venir »).

flow:            Server Component → header → grille de 4 cartes
                 cliquables (Link) → aucun état, aucun fetch.

ecosystem:       Miam = [
                   "@/app/miam/layout.tsx",
                   "@/app/miam/admin/layout.tsx",
                   "@/app/miam/admin/page.tsx",
                   "@/app/miam/components/MiamNav.tsx",
                 ]

relatedFiles:    ["@/app/miam/admin/layout.tsx"]

imports:         ["next", "next/link", "lucide-react"]

exports:         ["default MiamAdminPage", "metadata"]

useBy:           []

userStories:     ["*en tant qu'admin je veux un hub des sections métier"]

status:          wip
pathChecked:     ✔true
metaDataChecked: ✔true
scriptChecked:   ✔true
*/

import type { Metadata } from "next";
import Link from "next/link";
import {
  ArrowRight,
  Bike,
  Package,
  ShoppingBag,
  Store,
  type LucideIcon,
} from "lucide-react";

export const metadata: Metadata = {
  title: "Admin — Miam",
  description:
    "Administration de l'application métier Miam : commandes, catalogue, commerces, livreurs.",
};

interface AdminTile {
  readonly href: string;
  readonly title: string;
  readonly description: string;
  readonly icon: LucideIcon;
  readonly accent: string;
}

const TILES: readonly AdminTile[] = [
  {
    href: "/miam/admin/orders",
    title: "Commandes",
    description:
      "Suivre les commandes en cours, gérer les annulations, exporter l'historique.",
    icon: ShoppingBag,
    accent: "chart-1",
  },
  {
    href: "/miam/admin/catalog",
    title: "Catalogue",
    description:
      "Types de commerçants, de produits et de cuisines. Visibilité et ordre.",
    icon: Package,
    accent: "chart-2",
  },
  {
    href: "/miam/admin/merchants",
    title: "Commerces",
    description:
      "Valider les inscriptions, suspendre un commerce, suivre les mises en ligne.",
    icon: Store,
    accent: "chart-3",
  },
  {
    href: "/miam/admin/couriers",
    title: "Livreurs",
    description:
      "Gérer les comptes livreurs, les zones actives et la rémunération.",
    icon: Bike,
    accent: "chart-5",
  },
];

export default function MiamAdminPage() {
  return (
    <div className="space-y-6">
      <header className="space-y-1">
        <h2 className="text-2xl font-bold tracking-tight text-foreground">
          Administration
        </h2>
        <p className="text-sm text-muted-foreground">
          Accès réservé aux rôles <strong>admin</strong>, <strong>dev</strong> et{" "}
          <strong>superAdmin</strong>.
        </p>
      </header>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        {TILES.map((tile) => {
          const Icon = tile.icon;
          const accent = tile.accent;
          return (
            <Link
              key={tile.href}
              href={tile.href}
              className="group relative flex h-full flex-col overflow-hidden rounded-2xl border border-border/60 bg-card p-5 shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              style={{ "--accent": `var(--${accent})` } as React.CSSProperties}
            >
              <div
                aria-hidden
                className="absolute inset-x-0 top-0 h-1 opacity-70"
                style={{
                  background: `linear-gradient(90deg, var(--${accent}), transparent)`,
                }}
              />
              <header className="mb-3 flex items-center gap-3">
                <div
                  className="grid size-10 shrink-0 place-items-center rounded-xl text-white shadow-md"
                  style={{
                    background: `linear-gradient(135deg, var(--${accent}), color-mix(in oklab, var(--${accent}) 60%, black))`,
                  }}
                >
                  <Icon className="size-5" aria-hidden />
                </div>
                <h3 className="text-base font-bold tracking-tight text-foreground">
                  {tile.title}
                </h3>
              </header>
              <p className="flex-1 text-sm leading-relaxed text-muted-foreground">
                {tile.description}
              </p>
              <div className="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-foreground/80 transition-transform group-hover:translate-x-0.5">
                Ouvrir
                <ArrowRight className="size-4" aria-hidden />
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

/*
path :           app/auth/login/LoginForm.tsx
projectId:       new-genesis
type:            component
generic:         false

role:            Formulaire de connexion email + mot de passe. Utilise react-hook-form,
                 zodResolver(loginSchema), PasswordInput et Field shadcn.

flow:            Client Component → useForm → onSubmit → signIn.email() → si erreur :
                 setFormError avec message adapté (401/400/429/autre) → si succès :
                 toast + router.replace(callbackUrl) + router.refresh().

ecosystem:       Auth = [
                   "@/app/api/auth/[...all]/route.ts",
                   "@/app/auth/layout.tsx",
                   "@/app/auth/login/LoginForm.tsx",
                   "@/app/auth/login/page.tsx",
                   "@/app/auth/register/RegisterForm.tsx",
                   "@/app/auth/register/page.tsx",
                   "@/app/auth/welcome/page.tsx",
                   "@/components/auth/PasswordInput.tsx",
                   "@/components/auth/PasswordStrength.tsx",
                   "@/lib/auth/auth-client.ts",
                   "@/lib/auth/auth.ts",
                   "@/lib/auth/session.ts",
                   "@/lib/validations/auth.ts",
                 ]

relatedFiles:    ["@/app/auth/login/page.tsx",
                  "@/components/auth/PasswordInput.tsx",
                  "@/lib/auth/auth-client.ts",
                  "@/lib/validations/auth.ts",
                  "@/components/ui/alert.tsx",
                  "@/components/ui/button.tsx",
                  "@/components/ui/field.tsx",
                  "@/components/ui/input.tsx"]

imports:         ["react", "next/link", "next/navigation",
                  "react-hook-form", "@hookform/resolvers/zod",
                  "lucide-react", "sonner",
                  "@/components/ui/alert",
                  "@/components/ui/button",
                  "@/components/ui/field",
                  "@/components/ui/input",
                  "@/components/auth/PasswordInput",
                  "@/lib/auth/auth-client",
                  "@/lib/validations/auth"]

exports:         ["LoginForm", "LoginFormProps"]

useBy:           ["@/app/auth/login/page.tsx"]

userStories:     ["*en tant qu'utilisateur je veux me connecter avec mon email"]

status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";
// "use client" justifié : useState, useForm, useRouter, toast, interactions utilisateur.

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { AlertCircle, ArrowRight, Loader2, Lock, Mail } from "lucide-react";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { PasswordInput } from "@/components/auth/PasswordInput";
import { signIn } from "@/lib/auth/auth-client";
import {
  loginSchema,
  type LoginInput,
} from "@/lib/validations/auth";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface LoginFormProps {
  readonly callbackUrl: string;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function LoginForm({ callbackUrl }: LoginFormProps) {
  const router = useRouter();
  const [formError, setFormError] = useState<string | null>(null);
  const [redirecting, setRedirecting] = useState(false);

  const {
    control,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<LoginInput>({
    resolver: zodResolver(loginSchema),
    defaultValues: { email: "", password: "" },
    mode: "onBlur",
    reValidateMode: "onChange",
  });

  const isPending = isSubmitting || redirecting;

  async function onSubmit(values: LoginInput) {
    setFormError(null);

    try {
      const { error } = await signIn.email({
        email: values.email,
        password: values.password,
      });

      if (error) {
        if (error.status === 401 || error.status === 400) {
          setFormError("Email ou mot de passe incorrect.");
        } else if (error.status === 429) {
          setFormError("Trop de tentatives. Réessayez dans un instant.");
        } else {
          setFormError(error.message ?? "Connexion impossible. Réessayez.");
        }
        return;
      }

      setRedirecting(true);
      toast.success("Connexion réussie");
      router.replace(callbackUrl);
      router.refresh();
    } catch {
      setFormError(
        "Impossible de joindre le serveur. Vérifiez votre connexion.",
      );
    }
  }

  return (
    <div className="rounded-2xl border border-border bg-card p-6 shadow-xl shadow-chart-1/5 sm:p-8">
      {/* En-tête */}
      <div className="mb-8 space-y-3">
        <span className="grid size-11 place-items-center rounded-xl bg-gradient-to-br from-chart-1 to-chart-2 text-white shadow-lg shadow-chart-2/30">
          <Lock className="size-5" aria-hidden />
        </span>
        <h1 className="bg-gradient-to-r from-chart-1 via-chart-2 to-chart-3 bg-clip-text text-3xl font-bold tracking-tight text-transparent">
          Bon retour
        </h1>
        <p className="text-sm text-muted-foreground">
          Connectez-vous pour retrouver vos projets.
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5" noValidate>
        {formError && (
          <Alert variant="destructive" role="alert">
            <AlertCircle className="size-4" aria-hidden />
            <AlertDescription>{formError}</AlertDescription>
          </Alert>
        )}

        {/* Email */}
        <Field data-invalid={errors.email ? "" : undefined}>
          <FieldLabel htmlFor="login-email">Email</FieldLabel>
          <div className="relative">
            <Mail
              className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"
              aria-hidden
            />
            <Controller
              control={control}
              name="email"
              render={({ field }) => (
                <Input
                  {...field}
                  id="login-email"
                  type="email"
                  inputMode="email"
                  autoComplete="email"
                  placeholder="vous@exemple.com"
                  className="h-11 pl-10"
                  aria-invalid={errors.email ? true : undefined}
                />
              )}
            />
          </div>
          {errors.email?.message && (
            <FieldError errors={[{ message: errors.email.message }]} />
          )}
        </Field>

        {/* Mot de passe */}
        <Field data-invalid={errors.password ? "" : undefined}>
          <FieldLabel htmlFor="login-password">Mot de passe</FieldLabel>
          <Controller
            control={control}
            name="password"
            render={({ field }) => (
              <PasswordInput
                {...field}
                id="login-password"
                autoComplete="current-password"
                placeholder="Votre mot de passe"
                aria-invalid={errors.password ? true : undefined}
              />
            )}
          />
          {errors.password?.message && (
            <FieldError errors={[{ message: errors.password.message }]} />
          )}
        </Field>

        <Button
          type="submit"
          disabled={isPending}
          className="h-11 w-full gap-2 bg-gradient-to-r from-chart-1 via-chart-2 to-chart-3 text-base font-semibold text-white shadow-lg shadow-chart-2/25 transition hover:brightness-110 disabled:opacity-70"
        >
          {isPending ? (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden />
              Connexion…
            </>
          ) : (
            <>
              Se connecter
              <ArrowRight className="size-4" aria-hidden />
            </>
          )}
        </Button>
      </form>

      <p className="mt-8 text-center text-sm text-muted-foreground">
        Pas encore de compte ?{" "}
        <Link
          href="/auth/register"
          className="font-semibold text-chart-1 hover:underline"
        >
          Créer un compte
        </Link>
      </p>
    </div>
  );
}

