projectId:       new-genesis
type:            component
generic:         false

role:            Formulaire d'inscription : image de profil (file picker, stockée
                 en base64), nom, email, mot de passe avec indicateur de force,
                 confirmation. L'image est lue via FileReader.readAsDataURL() et
                 transmise à BetterAuth sous forme de data URL base64.

flow:            Client Component → useForm + zodResolver(registerSchema) →
                 useWatch pour l'aperçu en direct → handleFileChange lit le
                 fichier (max 2 Mo) → onSubmit appelle signUp.email() → si
                 erreur USER_ALREADY_EXISTS/422 : setError sur email ; si 429 :
                 formError ; sinon : formError → si succès : toast +
                 router.replace(callbackUrl) + router.refresh().

ecosystem:       Auth = [
                   "@/app/api/auth/[...all]/route.ts",
                   "@/app/auth/layout.tsx",
                   "@/app/auth/login/LoginForm.tsx",
                   "@/app/auth/login/page.tsx",
                   "@/app/auth/register/RegisterForm.tsx",
                   "@/app/auth/register/page.tsx",
                   "@/app/auth/welcome/page.tsx",
                   "@/components/auth/PasswordInput.tsx",
                   "@/components/auth/PasswordStrength.tsx",
                   "@/lib/auth/auth-client.ts",
                   "@/lib/auth/auth.ts",
                   "@/lib/auth/session.ts",
                   "@/lib/validations/auth.ts",
                 ]

relatedFiles:    ["@/app/auth/register/page.tsx",
                  "@/components/auth/PasswordInput.tsx",
                  "@/components/auth/PasswordStrength.tsx",
                  "@/lib/auth/auth-client.ts",
                  "@/lib/utils/initials.ts",
                  "@/lib/validations/auth.ts",
                  "@/components/ui/alert.tsx",
                  "@/components/ui/avatar.tsx",
                  "@/components/ui/button.tsx",
                  "@/components/ui/field.tsx",
                  "@/components/ui/input.tsx"]

imports:         ["react", "next/link", "next/navigation",
                  "react-hook-form", "@hookform/resolvers/zod",
                  "lucide-react", "sonner",
                  "@/components/ui/alert",
                  "@/components/ui/avatar",
                  "@/components/ui/button",
                  "@/components/ui/field",
                  "@/components/ui/input",
                  "@/components/auth/PasswordInput",
                  "@/components/auth/PasswordStrength",
                  "@/lib/auth/auth-client",
                  "@/lib/utils/initials",
                  "@/lib/validations/auth"]

exports:         ["RegisterForm", "RegisterFormProps"]

useBy:           ["@/app/auth/register/page.tsx"]

userStories:     ["*en tant qu'utilisateur je veux créer un compte avec mon email"]

