import {
  ArrowRight,
  Layers,
  LayoutDashboard,
  Lightbulb,
  ListChecks,
  ListTodo,
  Rocket,
  Sparkles,
  Users,
  type LucideIcon,
} from "lucide-react";

import { SCRUM_FLOWS, type ScrumFlow } from "@/app/scrum/lib/types";
import { listIdees } from "@/app/scrum/lib/services/idee";
import { listFeatures } from "@/app/scrum/lib/services/feature";
