export const taskInputSchema = z.object({
  title: requiredText(200),
  description: optionalText(2000),
  status: z.enum(["todo", "in_progress", "done"]),
  storyId: optionalText(100),
  assignee: optionalText(100),
  estimate: optionalText(100),
});

export type TaskInput = z.input<typeof taskInputSchema>;

/* ------------------------------------------------------------------ */
/*  Document complet                                                   */
/* ------------------------------------------------------------------ */

const entityBaseSchema = z
  .object({
    id: z.string().min(1),
    createdAt: z.string().min(1),
    updatedAt: z.string().min(1),
    order: z.number().int().min(0).default(0),
  })
  .strict();

export const scrumDocumentSchema = z
  .object({
    idea: z.array(
      entityBaseSchema
        .extend({
          title: z.string(),
          problem: z.string(),
          hypotheses: z.string(),
          context: z.string().optional(),
        })
        .strict(),
    ),
    feature: z.array(
      entityBaseSchema
        .extend({
          title: z.string(),
          description: z.string(),
          interest: z.string(),
          personas: z.array(z.string()),
        })
        .strict(),
    ),
    persona: z.array(
      entityBaseSchema
        .extend({
          name: z.string(),
          kind: z.string(),
          need: z.string(),
          relatedFeatures: z.array(z.string()),
        })
        .strict(),
    ),
    epic: z.array(
      entityBaseSchema
        .extend({
          name: z.string(),
          goal: z.string(),
          scope: z.string(),
          personas: z.array(z.string()),
        })
        .strict(),
    ),
    userStory: z.array(
      entityBaseSchema
        .extend({
          title: z.string(),
          story: z.string(),
          acceptance: z.string(),
          estimate: z.string().optional(),
          epicId: z.string().optional(),
        })
        .strict(),
    ),
    sprint: z.array(
      entityBaseSchema
        .extend({
          name: z.string(),
          goal: z.string(),
          storyIds: z.array(z.string()),
          startDate: z.string().optional(),
          endDate: z.string().optional(),
        })
        .strict(),
    ),
    task: z
      .array(
        entityBaseSchema
          .extend({
            title: z.string(),
            description: z.string().optional(),
            status: z.enum(["todo", "in_progress", "done"]),
            storyId: z.string().optional(),
            assignee: z.string().optional(),
            estimate: z.string().optional(),
          })
          .strict(),
      )
      .default([]),
    meta: z
      .object({
        schemaVersion: z.number().int().positive(),
        updatedAt: z.string().min(1),
      })
      .strict(),
  })
  .strict();

export type ScrumDocumentInput = z.input<typeof scrumDocumentSchema>;

/* ------------------------------------------------------------------ */
/*  Réordonnancement (payload d'action)                                */
/* ------------------------------------------------------------------ */

export const reorderInputSchema = z
  .object({
    orderedIds: z
      .array(z.string().min(1))
      .min(1)
      .refine((ids) => new Set(ids).size === ids.length, {
        message: "Ids dupliqués : chaque id doit apparaître une seule fois.",
      }),
  })
  .strict();

export type ReorderInput = z.input<typeof reorderInputSchema>;

