"use client";
// "use client" justifié : useState + useActionResult.

import { useState } from "react";

import { updateUserPlatformRoleAction } from "@/app/super-admin/user-manager/actions";
import {
  PLATFORM_ROLES,
  PLATFORM_ROLE_LABELS,
  platformRoleSchema,
  type PlatformRole,
} from "@/config/roles";
import {
  NativeSelect,
  NativeSelectOption,
} from "@/components/ui/native-select";
import { useActionResult } from "@/hooks/useActionResult";

/* ------------------------------------------------------------------ */
/*  Props                                                              */
/* ------------------------------------------------------------------ */

export interface RoleSelectProps {
  readonly userId: string;
  readonly currentRole: PlatformRole;
  readonly disabled?: boolean;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function RoleSelect({
  userId,
  currentRole,
  disabled = false,
}: RoleSelectProps) {
  const [role, setRole] = useState<PlatformRole>(currentRole);
  const { run, isPending } = useActionResult();

  function handleChange(nextRole: string) {
    /* La valeur vient d'un <NativeSelect> alimenté par PLATFORM_ROLES,
       mais on valide quand même via Zod : c'est la source de vérité
       unique, et cela protège contre un <option> injecté ou une
       évolution future de l'enum. */
    const parsed = platformRoleSchema.safeParse(nextRole);
    if (!parsed.success) {
      return;
    }

    const typedRole = parsed.data;
    const previous = role;
    setRole(typedRole);

    run(() => updateUserPlatformRoleAction(userId, typedRole), {
      successMessage: `Rôle mis à jour : ${PLATFORM_ROLE_LABELS[typedRole]}.`,
      rollback: () => setRole(previous),
    });
  }

  return (
    <NativeSelect
      value={role}
      onChange={(e) => handleChange(e.target.value)}
      disabled={disabled || isPending}
      className="w-40"
      aria-label="Rôle plateforme de l'utilisateur"
    >
      {PLATFORM_ROLES.map((r) => (
        <NativeSelectOption key={r} value={r}>
          {PLATFORM_ROLE_LABELS[r]}
        </NativeSelectOption>
      ))}
    </NativeSelect>
  );
}

